import { chromium } from 'playwright'

const browser = await chromium.launch()
const page = await browser.newPage({ viewport: { width: 1200, height: 800 } })
const errors = []
page.on('console', (msg) => {
  if (msg.type() === 'error') errors.push(msg.text())
})
page.on('pageerror', (err) => errors.push(String(err)))

await page.goto('http://localhost:3000', { waitUntil: 'networkidle' })
await page.waitForSelector('text=Products')

// Check that ViewTransition CSS classes exist as expected
const hasMorphRule = await page.evaluate(() => {
  return [...document.styleSheets].some((sheet) => {
    try {
      return [...sheet.cssRules].some((r) => r.cssText.includes('morph'))
    } catch {
      return false
    }
  })
})
console.log('has morph CSS rule:', hasMorphRule)

// Click and immediately sample animations mid-flight
await page.click('.product-card >> nth=0')
let sawAnimations = false
let names = []
for (let i = 0; i < 10; i++) {
  const info = await page.evaluate(() => ({
    count: document.getAnimations().length,
    names: document.getAnimations().map((a) => a.animationName || a.id || 'unknown'),
    hasActiveVT: !!document.activeViewTransition,
  }))
  if (info.count > 0) {
    sawAnimations = true
    names = info.names
    break
  }
  await page.waitForTimeout(30)
}
console.log('saw in-flight animations:', sawAnimations, names)

await page.waitForTimeout(300)
await page.screenshot({ path: '/tmp/pwtest/mid-detail.png' })
await page.waitForSelector('.product-detail')

console.log('ERRORS:', JSON.stringify(errors, null, 2))
await browser.close()

